"use strict";

// Round Table Orchestrator (RTO) v0.1
// 圓桌會議編排器：教練發訊息進「頂級特助分工群」→ 注入圓桌議程到學長 context
// 設計依據：knowledges/RTO_圓桌會議編排器設計.md / hooks/round-table-orchestrator/HOOK.md
// 教練親口指令 2026-06-09：「A+B+C 全要、不拆分、保留人格、不要當搬運工」

const fs = require('fs');
const path = require('path');
const https = require('https');

const TARGET_GROUP_CHAT_ID = '-1003877502911';   // 頂級特助分工群
const COACH_USER_ID = 6124913915;                // 大樹教練的 Telegram user_id
const MAIN_AGENT_ID = 'main';                    // 只在學長身上跑 RTO
const MINIMAX_API_URL = 'https://api.minimax.io/anthropic/v1/messages';
const MODEL_ID = 'MiniMax-M3';

// 不限流，每條教練訊息都可叫一次 LLM 生議程
const AGENDA_CACHE_FILE = '/tmp/openclaw/rto_recent_agendas.json';
const COOLDOWN_MS = 60_000;  // 同教練訊息 60 秒內不重複生議程

function loadCache() {
  try {
    if (!fs.existsSync(AGENDA_CACHE_FILE)) return {};
    return JSON.parse(fs.readFileSync(AGENDA_CACHE_FILE, 'utf-8'));
  } catch { return {}; }
}

function saveCache(cache) {
  try {
    fs.mkdirSync(path.dirname(AGENDA_CACHE_FILE), { recursive: true });
    fs.writeFileSync(AGENDA_CACHE_FILE, JSON.stringify(cache), 'utf-8');
  } catch {}
}

function isInCooldown(text) {
  const cache = loadCache();
  const key = String(text).slice(0, 80);
  const now = Date.now();
  if (cache[key] && (now - cache[key]) < COOLDOWN_MS) return true;
  cache[key] = now;
  // 順手清舊
  for (const k of Object.keys(cache)) {
    if (now - cache[k] > 600_000) delete cache[k];
  }
  saveCache(cache);
  return false;
}

async function generateAgenda(coachMessage) {
  const apiKey = process.env.MINIMAX_API_KEY;
  if (!apiKey) return null;

  const prompt = `你是「頂級特助分工群」的圓桌會議編排員。
群組成員：
- 學長（main，1號機）：中樞軍師，最終收尾呈報教練
- 學弟（kong，2號機）：執行者，擅長外部資料調查
- 學妹（peipei，3號機）：執行者，擅長整理彙總
- VPS H：跨系統顧問，提供外部視角

教練剛剛說：「${coachMessage.slice(0, 500)}」

請判斷這是不是一個「需要多 agent 協作」的話題。
- 若是：用 80 字以內生出「圓桌議程」，給學長作為執行建議
- 若不是（純打招呼、單純提問、純情感交流）：回應「【SKIP】」

議程格式：
建議圓桌流程：
① 誰先做什麼（時間/動作）
② 誰補刀什麼
③ 學長何時收尾呈報教練

只回議程或【SKIP】，不要其他文字。`;

  return new Promise((resolve) => {
    const body = JSON.stringify({
      model: MODEL_ID,
      max_tokens: 400,
      messages: [{ role: 'user', content: prompt }]
    });

    const req = https.request(MINIMAX_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01'
      },
      timeout: 8000
    }, (res) => {
      let chunks = '';
      res.on('data', (d) => chunks += d);
      res.on('end', () => {
        try {
          const json = JSON.parse(chunks);
          // M3 回應有 thinking + text 兩塊，要遍歷找 type=='text'
          // 參考：feedback_minimax_m3_api_parser.md
          const blocks = json.content || [];
          for (const b of blocks) {
            if (b.type === 'text' && b.text) {
              const text = b.text.trim();
              if (text.startsWith('【SKIP】')) return resolve(null);
              return resolve(text);
            }
          }
          resolve(null);
        } catch {
          resolve(null);
        }
      });
    });

    req.on('error', () => resolve(null));
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.write(body);
    req.end();
  });
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const ctx = event.context;
  const chatId = String(ctx.chatId ?? '');
  const userId = ctx.userId ?? ctx.fromUserId ?? ctx.from?.id;
  const agentId = ctx.agentId ?? '';
  const text = ctx.textContent ?? ctx.content ?? '';

  // 只在頂級特助分工群 + 學長身上 + 教練發的訊息 + 有內容
  if (chatId !== TARGET_GROUP_CHAT_ID) return;
  if (agentId !== MAIN_AGENT_ID) return;
  if (Number(userId) !== COACH_USER_ID) return;
  if (!text || text.trim().length < 5) return;

  // 60 秒內同訊息不重複生議程
  if (isInCooldown(text)) return;

  try {
    const agenda = await generateAgenda(text);
    if (!agenda) return;  // SKIP 或失敗 → 不注入

    const injection = [
      '---',
      '# 🍣 圓桌會議編排（RTO 自動生成）',
      '> 教練剛剛發話進群，根據話題複雜度，本次圓桌建議流程：',
      '',
      agenda,
      '',
      '> 提醒（守則#08 方向清楚直接執行）：照議程派發給學弟學妹，不要先反問教練。',
      '> 若議程明顯偏題，可微調或忽略——RTO 是建議不是強制。',
      '---'
    ].join('\n');

    if (!event.context.inject) event.context.inject = [];
    event.context.inject.push(injection);
  } catch (err) {
    // 靜默失敗，不影響訊息流轉
  }
};

module.exports = handler;
module.exports.default = handler;

